import sys
import json
import os
import hashlib

def compute_fingerprint(body):
    return hashlib.sha256(body.encode('utf-8')).hexdigest().lower()

def load_cache(cache_path):
    try:
        with open(cache_path, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return None

def save_cache(cache_path, records):
    with open(cache_path, 'w') as f:
        json.dump(records, f)

def generate_html(records):
    html = ['<!DOCTYPE html>', '<html>', '<head>', '</head>', '<body>']
    html.append(f'<h1>Tickets: {len(records)}</h1>')
    html.append('<table>')
    html.append('<tr><th>ID</th><th>Title</th><th>Body</th><th>Fingerprint</th></tr>')
    for record in records:
        fingerprint = compute_fingerprint(record['body'])
        html.append(f'<tr><td>{record["id"]}</td><td>{record["title"]}</td><td>{record["body"]}</td><td>{fingerprint}</td></tr>')
    html.append('</table>')
    html.append('</body>')
    html.append('</html>')
    return '\n'.join(html)

def main():
    if len(sys.argv) != 2:
        print("Usage: python tickets.py <path>")
        return

    json_path = sys.argv[1]
    cache_path = os.path.join(os.path.dirname(json_path), 'tickets.cache')

    if os.path.exists(cache_path):
        records = load_cache(cache_path)
    else:
        with open(json_path, 'r') as f:
            records = json.load(f)
        save_cache(cache_path, records)

    html = generate_html(records)
    print(html)

if __name__ == '__main__':
    main()

